final class Stock {
    private int remaining;
    Stock(int initial) {
        if (initial < 0) throw new IllegalArgumentException();
        remaining = initial;
    }
    void decrease(int quantity) {
        if (quantity <= 0 || quantity > remaining)
            throw new IllegalArgumentException();
        remaining -= quantity;
    }
    int remaining() { return remaining; }
}

