sealed interface Result permits Accepted, Rejected {}
record Accepted(long orderId) implements Result {}
record Rejected(String reason) implements Result {}
static String describe(Result result) {
    return switch (result) {
        case Accepted a -> "주문 " + a.orderId();
        case Rejected r -> "실패: " + r.reason();
    };
}

record OrderLine(long unitPrice, int quantity) {
    OrderLine {
        if (unitPrice < 0 || quantity <= 0)
            throw new IllegalArgumentException("가격·수량 오류");
    }
    long total() { return Math.multiplyExact(unitPrice, quantity); }
}

data class OrderLine(val unitPrice: Long, val quantity: Int) {
    init { require(unitPrice >= 0 && quantity > 0) }
    fun total(): Long = Math.multiplyExact(unitPrice, quantity.toLong())
}
